package com.lantanagroup.link.shared.audit;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.io.InputStream;
import java.time.Instant;
import java.util.List;

/**
 * The fixtures under src/test/resources/audit are what the .NET audit producer's serialiser writes, generated by
 * AuditEventMessageContractTests in ServiceTests, which also reads them with the Audit service's deserialiser.
 * The Java publisher's mapper must write the same JSON.
 */
public class AuditEventMessageContractTest {
    private static final Instant EVENT_DATE = Instant.parse("2026-11-23T15:04:05.123Z");

    // A plain mapper, so the fixture is read without any of the wire settings under test.
    private final ObjectMapper plain = new ObjectMapper();

    @Test
    public void serialize_updateEvent_matchesSharedFixture() throws IOException {
        AuditEventMessage event = new AuditEventMessage(
                "Hospital1", "Validation", null, EVENT_DATE, null, "nurse@hospital.example.org",
                AuditAction.UPDATE, "Category", "missing-required-element", "Patient/123",
                List.of(new PropertyChange("Title", "Old", "New"),
                        new PropertyChange("ApiKey", "[redacted]", "[redacted]")),
                null);

        Assertions.assertEquals(readFixture("audit-event-update.json"), AuditJson.wireMapper().valueToTree(event));
    }

    @Test
    public void serialize_createEvent_matchesSharedFixture() throws IOException {
        AuditEventMessage event = new AuditEventMessage(
                null, "MeasureEval", null, EVENT_DATE, null, null,
                AuditAction.CREATE, "MeasureDefinition", "measure-1", null,
                null, "measure-1 created");

        Assertions.assertEquals(readFixture("audit-event-create.json"), AuditJson.wireMapper().valueToTree(event));
    }

    private JsonNode readFixture(String name) throws IOException {
        try (InputStream stream = getClass().getResourceAsStream("/audit/" + name)) {
            Assertions.assertNotNull(stream, "Missing fixture " + name);
            return plain.readTree(stream);
        }
    }
}
